(async()=>{const out=[];for(const prevent of [false,true]){const c=new OffscreenCanvas(2,2),g=c.getContext('webgl2'),e=g.getExtension('WEBGL_lose_context'),events=[];c.addEventListener('webglcontextlost',v=>{events.push(v.type);if(prevent)v.preventDefault()});c.addEventListener('webglcontextrestored',v=>events.push(v.type));e.loseContext();g.getError();e.restoreContext();const early=g.getError();await new Promise(r=>setTimeout(r,20));e.restoreContext();const late=g.getError();await new Promise(r=>setTimeout(r,60));out.push({prevent,early,late,lost:g.isContextLost(),events})}return out})()
